import heapq
from itertools import product


def _route(data, coupon_rule, minimum_duration):
    required = data.get("required", [])
    full = (1 << len(required)) - 1
    initial_mask = sum(1 << i for i, node in enumerate(required)
                       if node == data["source"])
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start = (data["source"], initial_mask, 0)
    distances = {start: data["start"]}
    queue = [(data["start"], data["source"], initial_mask, 0)]
    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if distances.get(state) != time:
            continue
        if (node == data["target"] and mask == full and
                (coupon_rule == "at_most" or used == data["coupons"])):
            return {"arrival": time}

        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], used)]
            if used < data["coupons"]:
                duration = max(minimum_duration,
                               edge["duration"] - edge.get("discount", 0))
                choices.append((duration, used + 1))
            for duration, next_used in choices:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask
                for i, required_node in enumerate(required):
                    if next_node == required_node:
                        next_mask |= 1 << i
                next_state = (next_node, next_mask, next_used)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_used))
    return {"arrival": None}


def _component_01():
    return lambda data: _route(data, "exact", 1)


def _component_02():
    return lambda data: _route(data, "at_most", 2)


def _component_03():
    return lambda data: _route(data, "exact", 2)


def _component_04():
    return lambda data: _route(data, "at_most", 1)


def _component_05():
    return lambda data: _route(data, "exact", 1)


def _round(numerator, mode):
    if mode == "half_up":
        return (numerator + 5000) // 10000
    return numerator // 10000


def _component_06():
    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for position, event in enumerate(data["events"]):
            sequence = event.get("sequence", 0)
            if sequence > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            key = (sequence, event.get("revision", 0), position)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)

        balances = dict(data.get("opening", {}))
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = _round(raw * (10000 - discount), data["rounding"])
            tax = _round(net * event.get("tax_bp", 0), data["rounding"])
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = (event.get("account", "default") + "|" +
                   event.get("currency", "USD"))
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        roots = data["roots"]
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})

        # Each assignment selects no version or one available version per package.
        choices = []
        for name in names:
            rows = packages[name]
            allowed = [None]
            for row in rows:
                version = row["version"]
                if version in blocked.get(name, []):
                    continue
                if name in pins and version != pins[name]:
                    continue
                allowed.append(row)
            choices.append(allowed)

        best_vector = None
        best_versions = None
        for assignment in product(*choices):
            selected = {name: row for name, row in zip(names, assignment)
                        if row is not None}
            valid = True
            for name, (low, high) in roots.items():
                row = selected.get(name)
                if row is None or not low <= row["version"] <= high:
                    valid = False
                    break
            if not valid:
                continue

            edges = {name: [] for name in selected}
            for name, row in selected.items():
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = selected.get(dep["name"])
                    if (target is None or
                            not dep["min"] <= target["version"] <= dep["max"]):
                        valid = False
                        break
                    edges[name].append(dep["name"])
                if not valid:
                    break
            if not valid:
                continue

            # The selected packages must be exactly the active closure of roots.
            reached = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reached:
                    continue
                reached.add(name)
                if name not in selected:
                    valid = False
                    break
                stack.extend(edges[name])
            if not valid or reached != set(selected):
                continue

            finished, active = set(), set()
            def acyclic(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                if any(not acyclic(child) for child in edges[name]):
                    return False
                active.remove(name)
                finished.add(name)
                return True

            if not all(acyclic(name) for name in selected):
                continue

            vector = tuple(selected[name]["version"] if name in selected else -1
                           for name in names)
            if best_vector is None or vector > best_vector:
                best_vector = vector
                best_versions = {name: row["version"]
                                 for name, row in selected.items()}

        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _component_08():
    def feasible(selected, data):
        ids = {job["id"] for job in selected}
        if not set(data.get("mandatory", [])).issubset(ids):
            return False
        counts = {}
        for job in selected:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        for group, (low, high) in data.get("quotas", {}).items():
            if not low <= counts.get(group, 0) <= high:
                return False
        active = []
        for job in sorted(selected, key=lambda item: (item["start"], item["end"])):
            while active and active[0] <= job["start"]:
                heapq.heappop(active)
            heapq.heappush(active, job["end"])
            if len(active) > 2:
                return False
        return True

    def solve(data):
        options = [job for job in data["jobs"]
                   if job["id"] not in data.get("blocked", [])]
        k = data["k"]
        best_value = None
        best_ids = None
        for selected in __import__("itertools").combinations(options, k):
            if not feasible(selected, data):
                continue
            value = sum(job["value"] for job in selected)
            ids = tuple(sorted(job["id"] for job in selected))
            if (best_value is None or value > best_value or
                    (value == best_value and ids > best_ids)):
                best_value, best_ids = value, ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


